                    dailyTaskDraftRatio = newConfig?.activePolicy?.testsPerActiveApp ?: ratio,
                    dailyTaskDraftEffectiveFrom = defaultTomorrow,
                    dailyTaskDraftNote = "",
                    dailyTaskHistory = emptyList(),
                    dailyTaskHistoryCursorId = null,
                    dailyTaskHistoryHasMore = false,
                )
            }
