import com.ntt.crosstest.data.HomeStatsPolicyConfig
import com.ntt.crosstest.data.Localizer
import com.ntt.crosstest.data.Profile
import com.ntt.crosstest.data.SessionCacheManager
import io.github.jan.supabase.SupabaseClient
import io.github.jan.supabase.auth.Auth
import io.github.jan.supabase.auth.MemoryCodeVerifierCache
import io.github.jan.supabase.auth.MemorySessionManager
import io.github.jan.supabase.auth.auth
import io.github.jan.supabase.auth.user.UserSession
import io.github.jan.supabase.createSupabaseClient
import io.github.jan.supabase.postgrest.Postgrest
import io.ktor.client.engine.mock.MockEngine
import io.ktor.client.engine.mock.MockRequestHandleScope
import io.ktor.client.engine.mock.respond
import io.ktor.client.request.HttpRequestData
import io.ktor.client.request.HttpResponseData
import io.ktor.http.HttpHeaders
import io.ktor.http.HttpStatusCode
import io.ktor.http.headersOf
import kotlinx.coroutines.CompletableDeferred
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.ExperimentalCoroutinesApi
import kotlinx.coroutines.runBlocking
import kotlinx.coroutines.test.StandardTestDispatcher
import kotlinx.coroutines.test.TestCoroutineScheduler
import kotlinx.coroutines.test.UnconfinedTestDispatcher
import kotlinx.coroutines.test.resetMain
import kotlinx.coroutines.test.runTest
import kotlinx.coroutines.test.setMain
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json
import org.junit.After
import org.junit.Assert.*
import org.junit.Before
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.RuntimeEnvironment
import org.robolectric.annotation.Config
import java.util.UUID
import java.util.concurrent.atomic.AtomicInteger

@OptIn(ExperimentalCoroutinesApi::class)
@RunWith(RobolectricTestRunner::class)
@Config(application = Application::class, sdk = [34])
class AdminFlowSessionRaceTest {

    private val context: Application get() = RuntimeEnvironment.getApplication()
    private val localizer by lazy { Localizer(context) }
    private val json = Json { ignoreUnknownKeys = true }
    private val store = ViewModelStore()
    private val clientsToClose = mutableListOf<SupabaseClient>()

    private val adminA = "11111111-1111-1111-1111-111111111111"
    private val adminB = "22222222-2222-2222-2222-222222222222"
    private val userTarget = "33333333-3333-3333-3333-333333333333"

    @Before
    fun setup() {
        SessionCacheManager.clear(context)
    }

    @After
    fun cleanup() {
        store.clear()
        clientsToClose.forEach { runCatching { runBlocking { it.close() } } }
        clientsToClose.clear()
        SessionCacheManager.clear(context)
        Dispatchers.resetMain()
    }

    private fun MockRequestHandleScope.reply(body: String, status: HttpStatusCode = HttpStatusCode.OK) =
        respond(body, status, headersOf(HttpHeaders.ContentType, "application/json"))

    private fun createClient(handler: suspend MockRequestHandleScope.(HttpRequestData) -> HttpResponseData): SupabaseClient {
        val client = createSupabaseClient("https://fixture.invalid", "dummy-key") {
            install(Auth) {
                sessionManager = MemorySessionManager()
                codeVerifierCache = MemoryCodeVerifierCache()
                autoLoadFromStorage = false
                autoSaveToStorage = false
                enableLifecycleCallbacks = false
            }
            install(Postgrest)
            httpEngine = MockEngine(handler)
        }
        clientsToClose.add(client)
        return client
    }

    private suspend fun login(c: SupabaseClient, uid: String) {
        c.auth.importSession(
            json.decodeFromString<UserSession>(
                """{"access_token":"token-$uid","refresh_token":"ref-$uid","expires_in":3600,"token_type":"bearer","user":{"id":"$uid","aud":"authenticated"}}"""
            )
        )
    }

    private fun createAdminUsersVm(client: SupabaseClient): AdminUsersViewModel {
        val authRepo = AuthRepository(client, context)
        val appConfigRepo = AppConfigRepository(client, context)
        val campaignRepo = CampaignRepository(client, localizer)
        val vm = AdminUsersViewModel(campaignRepo, authRepo, appConfigRepo, localizer)
        store.put(UUID.randomUUID().toString(), vm)
        return vm
    }

    private fun createAdminReportsVm(client: SupabaseClient): AdminReportsViewModel {
        val authRepo = AuthRepository(client, context)
        val campaignRepo = CampaignRepository(client, localizer)
        val vm = AdminReportsViewModel(campaignRepo, localizer, authRepo)
        store.put(UUID.randomUUID().toString(), vm)
        return vm
    }

    // ---------------------------------------------------------------------------------------------
    // 1. Stale vs Newer Refresh Tests
    // ---------------------------------------------------------------------------------------------

    @Test
    fun delayed_stale_refresh_does_not_overwrite_newer_refresh_in_admin_users() = runTest {
        Dispatchers.setMain(UnconfinedTestDispatcher(testScheduler))

        val deferred1 = CompletableDeferred<String>()
        var requestIndex = 0

        val client = createClient { request ->
            val path = request.url.encodedPath
            if (path.contains("profiles")) {
                val idx = ++requestIndex
                if (idx == 1) {
                    val body = deferred1.await()
                    reply(body)
                } else {
                    reply(json.encodeToString(listOf(Profile(id = "user-new", email = "new@test.com"))))
                }
            } else {
                reply("[]")
            }
        }
        login(client, adminA)

        val vm = createAdminUsersVm(client)
        // vm init triggered request 1 which is hanging on deferred1
        assertEquals("Initial refresh should be loading", true, vm.uiState.value.isLoading)

        // Request 2 initiated: newer refresh
        vm.refresh(forceRefresh = true)
        testScheduler.runCurrent()

        assertEquals("Newer refresh should have published its list", 1, vm.uiState.value.allUsers.size)
        assertEquals("user-new", vm.uiState.value.allUsers.first().id)

        // Now request 1 (stale) finally resolves
        deferred1.complete(json.encodeToString(listOf(Profile(id = "user-old", email = "old@test.com"))))
        testScheduler.runCurrent()

        // Stale completion must NOT overwrite newer list
        assertEquals("Stale refresh must not overwrite newer list", "user-new", vm.uiState.value.allUsers.first().id)
        assertFalse(vm.uiState.value.isLoading)
    }

    @Test
    fun delayed_stale_refresh_does_not_overwrite_newer_refresh_in_admin_reports() = runTest {
        Dispatchers.setMain(UnconfinedTestDispatcher(testScheduler))

        val deferred1 = CompletableDeferred<String>()
        var requestIndex = 0

        val client = createClient { request ->
            val path = request.url.encodedPath
            if (path.contains("admin_get_contact_reports")) {
                val idx = ++requestIndex
                if (idx == 1) {
                    val body = deferred1.await()
                    reply(body)
                } else {
                    reply(json.encodeToString(listOf(ContactReport(id = "rep-new", userId = "u1", message = "New report"))))
                }
            } else {
                reply("[]")
            }
        }
        login(client, adminA)

        val vm = createAdminReportsVm(client)
        // Request 1 is waiting on deferred1
        assertTrue(vm.uiState.value.isLoading)

        // Newer refresh
        vm.refresh(forceRefresh = true)
        testScheduler.runCurrent()

        assertEquals("rep-new", vm.uiState.value.allReports.first().id)

        // Stale request finishes
        deferred1.complete(json.encodeToString(listOf(ContactReport(id = "rep-old", userId = "u2", message = "Old report"))))
        testScheduler.runCurrent()

        assertEquals("Stale refresh must not overwrite newer reports list", "rep-new", vm.uiState.value.allReports.first().id)
        assertFalse(vm.uiState.value.isLoading)
    }

    // ---------------------------------------------------------------------------------------------
    // 2. Refresh vs Mutation Tests
    // ---------------------------------------------------------------------------------------------

    @Test
    fun refresh_initiated_before_lock_mutation_does_not_overwrite_mutation_result() = runTest {
        Dispatchers.setMain(UnconfinedTestDispatcher(testScheduler))

        val deferredRefresh = CompletableDeferred<String>()
        var getProfilesCount = 0

        val client = createClient { request ->
            val path = request.url.encodedPath
            when {
                path.contains("admin_set_user_lock") -> {
                    reply(json.encodeToString(AdminSetUserLockResult(success = true, userId = userTarget, isLocked = true)))
                }
                path.contains("profiles") -> {
                    getProfilesCount++
                    if (getProfilesCount == 1) {
                        // First refresh is delayed and would return userTarget UNLOCKED
                        val body = deferredRefresh.await()
                        reply(body)
                    } else {
                        // Subsequent refresh after mutation returns userTarget LOCKED
                        reply(json.encodeToString(listOf(Profile(id = userTarget, isLocked = true))))
                    }
                }
                else -> reply("{}")
            }
        }
        login(client, adminA)

        val vm = createAdminUsersVm(client)
        // Request 1 is waiting on deferredRefresh

        // Admin mutates lock state: userTarget locked
        vm.setUserLock(userTarget, locked = true)
        testScheduler.runCurrent()

        // Mutation succeeded and triggered its fresh refresh (getProfilesCount == 2)
        assertEquals(2, getProfilesCount)
        assertTrue(vm.uiState.value.allUsers.first().isLocked)

        // Now first refresh resolves with userTarget UNLOCKED
        deferredRefresh.complete(json.encodeToString(listOf(Profile(id = userTarget, isLocked = false))))
        testScheduler.runCurrent()

        // Stale refresh must NOT overwrite the mutation result
        assertTrue("User lock state must remain locked after stale refresh returns", vm.uiState.value.allUsers.first().isLocked)
    }

    @Test
    fun refresh_initiated_before_report_reply_mutation_does_not_overwrite_replied_status() = runTest {
        Dispatchers.setMain(UnconfinedTestDispatcher(testScheduler))

        val deferredRefresh = CompletableDeferred<String>()
        var getReportsCount = 0

        val client = createClient { request ->
            val path = request.url.encodedPath
            when {
                path.contains("admin_reply_contact_report") -> {
                    reply("{}")
                }
                path.contains("admin_get_contact_reports") -> {
                    getReportsCount++
                    if (getReportsCount == 1) {
                        val body = deferredRefresh.await()
                        reply(body)
                    } else {
                        // Newer list after reply mutation
                        reply(json.encodeToString(listOf(ContactReport(id = "rep-1", userId = "u1", status = "replied", adminReply = "Handled"))))
                    }
                }
                else -> reply("[]")
            }
        }
        login(client, adminA)

        val vm = createAdminReportsVm(client)
        // Request 1 is waiting on deferredRefresh

        // Admin replies to contact report
        vm.replyTo("rep-1", "Handled")
        testScheduler.runCurrent()

        assertEquals(2, getReportsCount)
        assertEquals("replied", vm.uiState.value.allReports.first().status)

        // Stale refresh completes with status = "new"
        deferredRefresh.complete(json.encodeToString(listOf(ContactReport(id = "rep-1", userId = "u1", status = "new"))))
        testScheduler.runCurrent()

        assertEquals("Stale refresh must not roll back replied report status", "replied", vm.uiState.value.allReports.first().status)
    }

    // ---------------------------------------------------------------------------------------------
    // 3. Account Switch during in-flight operations
    // ---------------------------------------------------------------------------------------------

    @Test
    fun account_switch_during_in_flight_request_and_action_drops_old_response_and_clears_sensitive_state() = runTest {
        Dispatchers.setMain(UnconfinedTestDispatcher(testScheduler))

        val deferredProfilesA = CompletableDeferred<String>()
        val deferredConfigA = CompletableDeferred<String>()

        val client = createClient { request ->
            val path = request.url.encodedPath
            when {
                path.contains("profiles") -> {
                    val authHeader = request.headers[HttpHeaders.Authorization].orEmpty()
                    if (authHeader.contains(adminA)) {
                        reply(deferredProfilesA.await())
                    } else {
                        reply(json.encodeToString(listOf(Profile(id = "user-b-admin", email = "b@test.com"))))
                    }
                }
                path.contains("app_configs") -> {
                    val authHeader = request.headers[HttpHeaders.Authorization].orEmpty()
                    if (authHeader.contains(adminA)) {
                        reply(deferredConfigA.await())
                    } else {
                        reply(json.encodeToString(listOf(AppConfig(title = "Config for B"))))
                    }
                }
                else -> reply("[]")
            }
        }
        login(client, adminA)

        val vm = createAdminUsersVm(client)
        vm.loadAppConfig()
        testScheduler.runCurrent()

        // Both requests for admin A are currently in flight
        assertTrue(vm.uiState.value.isLoading || vm.uiState.value.isConfigLoading)
        assertEquals(adminA, vm.uiState.value.currentAdminId)

        // Switch to Admin B
        login(client, adminB)
        testScheduler.runCurrent()

        // Admin B should have cleared sensitive state of Admin A
        assertEquals(adminB, vm.uiState.value.currentAdminId)

        // Now Admin A's stale responses arrive
        deferredProfilesA.complete(json.encodeToString(listOf(Profile(id = "user-sensitive-a", email = "secret@admina.com"))))
        deferredConfigA.complete(json.encodeToString(listOf(AppConfig(title = "Secret Config A"))))
        testScheduler.runCurrent()

        // Verify Admin A's data was NOT published
        assertNull(vm.uiState.value.allUsers.find { it.id == "user-sensitive-a" })
        assertNotEquals("Secret Config A", vm.uiState.value.appConfig?.title)
    }

    // ---------------------------------------------------------------------------------------------
    // 4. Generation change for same UID
    // ---------------------------------------------------------------------------------------------

    @Test
    fun generation_change_for_same_uid_rejects_stale_response() = runTest {
        Dispatchers.setMain(UnconfinedTestDispatcher(testScheduler))

        val deferredStats = CompletableDeferred<String>()

        val client = createClient { request ->
            val path = request.url.encodedPath
            if (path.contains("admin_get_home_stats_config")) {
                reply(deferredStats.await())
            } else {
                reply("[]")
            }
        }
        login(client, adminA)

        val vm = createAdminUsersVm(client)
        testScheduler.runCurrent()

        // Admin A starts loading home stats config under generation 1
        vm.loadHomeStatsConfig()
        assertTrue(vm.uiState.value.isHomeStatsLoading)

        // Generation increments for same UID (logout / clear session cache / relogin)
        SessionCacheManager.clear(context)
        assertEquals("Generation must have incremented", 2L, SessionCacheManager.currentGeneration())

        // Stale response from generation 1 arrives
        deferredStats.complete(json.encodeToString(HomeStatsPolicyConfig(activeCycleDays = 7, revision = "gen1-rev")))
        testScheduler.runCurrent()

        // Must reject stale generation response
        assertNull("Generation 1 response must be dropped", vm.uiState.value.homeStatsConfig)
    }

    // ---------------------------------------------------------------------------------------------
    // 5. Double Action Submission on StandardTestDispatcher
    // ---------------------------------------------------------------------------------------------

    @Test
    fun double_action_submission_with_standard_test_dispatcher_admits_only_first_call() = runTest {
        val scheduler = TestCoroutineScheduler()
        val standardDispatcher = StandardTestDispatcher(scheduler)
        Dispatchers.setMain(standardDispatcher)

        val lockCallCount = AtomicInteger(0)
        val creditCallCount = AtomicInteger(0)
        val notifCallCount = AtomicInteger(0)
        val replyCallCount = AtomicInteger(0)
        val statusCallCount = AtomicInteger(0)

        val client = createClient { request ->
            val path = request.url.encodedPath
            when {
                path.contains("admin_set_user_lock") -> {
                    lockCallCount.incrementAndGet()
                    reply(json.encodeToString(AdminSetUserLockResult(success = true, userId = userTarget, isLocked = true)))
                }
                path.contains("admin_adjust_credits") -> {
                    creditCallCount.incrementAndGet()
                    reply(json.encodeToString(AdminAdjustCreditsResult(success = true, newCredits = 200, amount = 50)))
                }
                path.contains("admin_send_notification") -> {
                    notifCallCount.incrementAndGet()
                    reply("""{"sent_count":1}""")
                }
                path.contains("admin_reply_contact_report") -> {
                    replyCallCount.incrementAndGet()
                    reply("{}")
                }
                path.contains("admin_update_report_status") -> {
                    statusCallCount.incrementAndGet()
                    reply("{}")
                }
                else -> reply("[]")
            }
        }
        login(client, adminA)

        val usersVm = createAdminUsersVm(client)
        val reportsVm = createAdminReportsVm(client)
        scheduler.advanceUntilIdle()

        // Double submit setUserLock synchronously
        usersVm.setUserLock(userTarget, true)
        usersVm.setUserLock(userTarget, true)
        scheduler.advanceUntilIdle()
        assertEquals("Double setUserLock must dispatch exactly 1 network call", 1, lockCallCount.get())

        // Double submit adjustCredits synchronously
        usersVm.adjustCredits(userTarget, 50)
        usersVm.adjustCredits(userTarget, 50)
        scheduler.advanceUntilIdle()
        assertEquals("Double adjustCredits must dispatch exactly 1 network call", 1, creditCallCount.get())

        // Double submit sendNotification synchronously
        usersVm.sendNotification(userTarget, "T", "M")
        usersVm.sendNotification(userTarget, "T", "M")
        scheduler.advanceUntilIdle()
        assertEquals("Double sendNotification must dispatch exactly 1 network call", 1, notifCallCount.get())

        // Double submit replyTo synchronously
        reportsVm.replyTo("rep-1", "Msg")
        reportsVm.replyTo("rep-1", "Msg")
        scheduler.advanceUntilIdle()
        assertEquals("Double replyTo must dispatch exactly 1 network call", 1, replyCallCount.get())

        // Double submit setResolved synchronously
        reportsVm.setResolved("rep-1", true)
        reportsVm.setResolved("rep-1", true)
        scheduler.advanceUntilIdle()
        assertEquals("Double setResolved must dispatch exactly 1 network call", 1, statusCallCount.get())
    }

    // ---------------------------------------------------------------------------------------------
    // 6. Stale homeStats response does not clear current config/flags
    // ---------------------------------------------------------------------------------------------

    @Test
    fun stale_home_stats_response_does_not_clear_current_config_or_flags() = runTest {
        Dispatchers.setMain(UnconfinedTestDispatcher(testScheduler))

        val deferredOld = CompletableDeferred<String>()
        var getStatsCount = 0

        val client = createClient { request ->
            val path = request.url.encodedPath
            if (path.contains("admin_get_home_stats_config")) {
                val idx = ++getStatsCount
                if (idx == 1) {
                    reply(deferredOld.await())
                } else {
                    reply(json.encodeToString(HomeStatsPolicyConfig(activeCycleDays = 14, revision = "new-rev")))
                }
            } else {
                reply("[]")
            }
        }
        login(client, adminA)

        val vm = createAdminUsersVm(client)
        testScheduler.runCurrent()

        // Start request 1 (hanging on deferredOld)
        vm.loadHomeStatsConfig()
        assertTrue(vm.uiState.value.isHomeStatsLoading)

        // Start request 2 (newer)
        vm.loadHomeStatsConfig()
        testScheduler.runCurrent()

        assertEquals("Newer config must be active", 14, vm.uiState.value.homeStatsConfig?.activeCycleDays)
        assertFalse("Loading must be false after newer request completed", vm.uiState.value.isHomeStatsLoading)

        // Now stale request 1 resolves
        deferredOld.complete(json.encodeToString(HomeStatsPolicyConfig(activeCycleDays = 3, revision = "stale-rev")))
        testScheduler.runCurrent()

        // Must retain config 14 and must NOT have cleared homeStatsConfig to null or rolled back to 3
        assertEquals("Stale completion must not overwrite or null newer config", 14, vm.uiState.value.homeStatsConfig?.activeCycleDays)
        assertFalse(vm.uiState.value.isHomeStatsLoading)
    }

    // ---------------------------------------------------------------------------------------------
    // 7. Forced Refresh Error with Existing Data is not swallowed
    // ---------------------------------------------------------------------------------------------

    @Test
    fun forced_refresh_error_with_existing_data_is_surfaced_to_ui_state() = runTest {
        Dispatchers.setMain(UnconfinedTestDispatcher(testScheduler))

        var failProfiles = false
        var failReports = false

        val client = createClient { request ->
            val path = request.url.encodedPath
            when {
                path.contains("profiles") -> {
                    if (failProfiles) {
                        respond("Server error", HttpStatusCode.InternalServerError)
                    } else {
                        reply(json.encodeToString(listOf(Profile(id = "user-1", email = "u1@test.com"))))
                    }
                }
                path.contains("admin_get_contact_reports") -> {
                    if (failReports) {
                        respond("Server error", HttpStatusCode.InternalServerError)
                    } else {
                        reply(json.encodeToString(listOf(ContactReport(id = "rep-1", userId = "u1", message = "Hello"))))
                    }
                }
                else -> reply("[]")
            }
        }
        login(client, adminA)

        val usersVm = createAdminUsersVm(client)
        val reportsVm = createAdminReportsVm(client)
