    @Test
    fun compose_saveable_state_registry_primitive_roundtrip_and_session_draft_isolation() {
        val originalRegistry = SaveableStateRegistry(restoredValues = null) { true }

        val targetLockId = "user-lock-123"
        val targetCreditId = "user-credit-456"
        val targetNotifId = "user-notif-789"
        val targetReportId = "report-reply-012"

        val draftCreditAmount = "250"
        val draftCreditReason = "Special reward"
        val draftNotifTitle = "Urgent Notice"
        val draftNotifMsg = "Please read this note"
        val draftReplyMsg = "Thank you for the report"

        val sessionUid = adminA
        val sessionGen = 1L

        // Register values as rememberSaveable does with primitive values
        originalRegistry.registerProvider("target_lock_id") { targetLockId }
        originalRegistry.registerProvider("target_credit_id") { targetCreditId }
        originalRegistry.registerProvider("target_notif_id") { targetNotifId }
        originalRegistry.registerProvider("target_report_id") { targetReportId }

        originalRegistry.registerProvider("saved_session_uid") { sessionUid }
        originalRegistry.registerProvider("saved_session_gen") { sessionGen }

        // Register drafts keyed by target + session
        val creditKey = "credit_draft_${targetCreditId}_${sessionUid}_$sessionGen"
        originalRegistry.registerProvider("${creditKey}_amount") { draftCreditAmount }
        originalRegistry.registerProvider("${creditKey}_reason") { draftCreditReason }

        val notifKey = "notif_draft_${targetNotifId}_${sessionUid}_$sessionGen"
        originalRegistry.registerProvider("${notifKey}_title") { draftNotifTitle }
        originalRegistry.registerProvider("${notifKey}_msg") { draftNotifMsg }

        val replyKey = "reply_draft_${targetReportId}_${sessionUid}_$sessionGen"
        originalRegistry.registerProvider("${replyKey}_msg") { draftReplyMsg }

        // Save all registered values
        val savedValues = originalRegistry.performSave()

        // Verify bundle / primitive compatibility: all entries must be primitives / lists of primitives
        savedValues.forEach { (key, list) ->
            list.forEach { value ->
                assertTrue(
                    "Saved state value for '$key' must be a bundle primitive (String, Number, Boolean)",
                    value is String || value is Number || value is Boolean
                )
            }
        }

        // Scenario A: Restore in the SAME session (e.g. Activity recreation / screen rotation)
        val restoredRegistrySameSession = SaveableStateRegistry(restoredValues = savedValues) { true }

        val restoredSessionUid = restoredRegistrySameSession.consumeRestored("saved_session_uid") as? String
        val restoredSessionGen = restoredRegistrySameSession.consumeRestored("saved_session_gen") as? Long

        assertEquals(sessionUid, restoredSessionUid)
        assertEquals(sessionGen, restoredSessionGen)

        // Session matches -> target IDs and drafts are preserved
        val isSameSession = (restoredSessionUid == sessionUid && restoredSessionGen == sessionGen)
        assertTrue("Restored session identity matches current session", isSameSession)

        val restoredTargetCreditId = restoredRegistrySameSession.consumeRestored("target_credit_id") as? String
        assertEquals(targetCreditId, restoredTargetCreditId)

        val restoredAmount = restoredRegistrySameSession.consumeRestored("${creditKey}_amount") as? String
        val restoredReason = restoredRegistrySameSession.consumeRestored("${creditKey}_reason") as? String
        assertEquals(draftCreditAmount, restoredAmount)
        assertEquals(draftCreditReason, restoredReason)

        // Scenario B: Restore after account switch or generation bump (different UID or generation)
        val differentAdmin = adminB
        val differentGen = 2L

        // Keyed drafts for target with different admin must NOT match the saved draft
        val newCreditKey = "credit_draft_${targetCreditId}_${differentAdmin}_$differentGen"
        assertNull("Drafts must not leak across different admin identity", restoredRegistrySameSession.consumeRestored("${newCreditKey}_amount"))
    }
}

